n("ליר", "ליר הוא שם עברי חדש שקרוב למילה לירה, כלי נגינה עתיק עם מיתרים שמנגנים בו באצבעות. הלירה מוכרת מיוון העתיקה, וגם בארץ ניגנו בעת העתיקה בכלי מיתרים דומים, כמו הכינור. השם ניתן גם לבנים וגם לבנות, והוא נשמע גם כמו צירוף של לי ושל ר.", ["לירי"])
n("אליאנה", "אליאנה הוא שם חדש, וכנראה הוא בנוי מהמילים אלי וענה, ופירושו אלוהים ענה לי. בשפות של אירופה יש שם בצליל דומה, אליאנה, שמקורו בשם לטיני. השם נשמע קרוב לאליאן ולאנה.", ["אליאן"])
n("רונן", "רונן הוא שם עברי מהשורש ר־נ־ן, שממנו באות המילים רון, רינה ורננה, שירה ושמחה. פירושו שר בשמחה. השם היה נפוץ בארץ בשנות השישים והשבעים, ובאירית יש שם בצליל זהה עם מקור אחר.", ["רנן"])
n("קרין", "קרין הוא כתיב עברי של קארין, צורה סקנדינבית של השם קתרין, שבא מהיוונית. בעברית השם נשמע גם קרוב למילה קרן, קרן אור. השם היה נפוץ בארץ בשנות השבעים והשמונים.", ["קארין", "קארן"])
n("לישי", "לישי הוא שם עברי חדש שבנוי משתי מילים, לי ושי, ופירושו מתנה בשבילי. המילה שי היא מילה עתיקה למתנה, והיא מוכרת מהשפה העברית הקדומה. השם ניתן גם לבנים וגם לבנות.", [])
n("היילי", "היילי הוא שם אנגלי שבמקור היה שם משפחה, ופירושו אחו של חציר. באנגלית הוא נעשה שם נפוץ לבנות בשנות התשעים. בעברית השם נשמע גם קרוב להילה ולהילי, ויש הורים שבוחרים בו גם בגלל זה.", ["הילי"])
n("לינור", "לינור הוא שם עברי חדש שבנוי משתי מילים, לי ונור, ופירושו יש לי אור. המילה נור היא מילה ארמית שפירושה אש, והיא קרובה למילה העברית נר. השם היה נפוץ בארץ בשנות השמונים והתשעים.", [])
n("שגיב", "שגיב הוא שם עברי מהשורש ש־ג־ב, שממנו באות המילים נשגב ושגב, גובה ורוממות. פירושו נעלה ורם. מאותו שורש באה גם המילה משגב, מקום גבוה ובטוח. השם היה נפוץ בארץ בשנות השבעים.", ["שגב"])
n("הענא", "הענא הוא שם ביידיש, צורה של חנה. ביידיש נכתבת התנועה באות ע, ולכן השם נכתב כך. השם חנה בא מהשורש ח־נ־ן, שממנו באות המילים חן וחנינה, ובמסורת חנה היא אמו של שמואל הנביא.", [])
n("ליאנה", "ליאנה היא צמח מטפס ארוך שגדל ביערות הטרופיים, ונאחז בעצים כדי להגיע לאור. בשפות של אירופה ליאנה הוא גם שם, שנבנה כנראה כצורה קצרה של שמות כמו ג׳וליאנה ואיליאנה. השם נשמע גם קרוב ללי ולאנה.", [])
n("ריין", "ריין הוא שם קצר וחדש, וכנראה הוא קשור לשורש ר־נ־ן, שממנו באות המילים רון ורינה, שירה ושמחה. באנגלית המילה ריין פירושה גשם, ובגרמנית ריין הוא נהר גדול. השם ניתן גם לבנים וגם לבנות.", [])
n("מירל", "מירל הוא שם ביידיש, צורת חיבה של מרים. ביידיש נבנו צורות חיבה רבות עם הסיומת ל, כמו מירל, פרידל ושיינדל. השם היה נפוץ בקהילות של מזרח אירופה, ונשמר בקהילות חסידיות.", [])
n("אלעאי", "אלעאי הוא שמו של חכם בתלמוד, רבי אלעאי, שחי בימי המשנה, ובנו היה רבי יהודה בר אלעאי. השם כנראה קשור למילה עלאי, עליון, בארמית. בכתיב אחר הוא מוכר גם כאילעאי.", ["אילעאי", "אילעי"])
n("ניקיטה", "ניקיטה הוא שם רוסי, שבא מהשם היווני ניקטאס, מנצח. הוא קשור למילה היוונית ניקה, ניצחון, שממנה באים גם השמות ניקולאי ונקי. ברוסית ובאוקראינית השם נפוץ מאוד.", [])
n("סימא", "סימא הוא שם שבא מהארמית, שבה המילה סימא פירושה אוצר. השם היה נפוץ בקהילות של יהודי מזרח אירופה, ובקהילות אחרות מוכרת הצורה סימה. הכתיב עם האות א שומר על הצורה הארמית.", ["סימה"])
n("ענת", "ענת הוא שם קדום, ובספר שופטים שמגר בן ענת הוא אחד השופטים, שהכה בפלשתים. השם קשור כנראה לשורש ע־נ־ה, ענייה ותשובה. בעברית החדשה ענת הוא שם נפוץ לבנות, ומוכר בארץ מאז ימי העלייה הראשונה.", ["ענהאל", "ענאל"])
n("אנסטסיה", "אנסטסיה הוא שם יווני שבא מהמילה אנסטסיס, תקומה ותחייה. השם נפוץ מאוד ברוסיה ובשפות של מזרח אירופה, ושם מוכרות גם צורות החיבה נסטיה ואסיה. בעברית השם נשמע ארוך ומלכותי.", ["אסיה"])
n("ענאל", "ענאל הוא שם עברי חדש, וכנראה הוא בנוי מהמילים ענה ואל, ופירושו אלוהים ענה. מוכרת גם הצורה ענהאל, שבה המילה ענה נכתבת במלואה. כמו שמות רבים שמסתיימים באל, השם מתאר תפילה שהתקבלה.", ["ענהאל"])
n("מורי", "מורי הוא שם עברי שפירושו המורה שלי. בקהילות תימן מורי היה גם תואר של כבוד לרב ולמלמד. השם נשמע קרוב לשמות מור ומוריה, ובעברית של היום הוא ניתן בעיקר לבנים, לפעמים לזכר של סב או של רב.", ["מוריאל"])
n("שילי", "שילי הוא שם עברי חדש שבנוי משתי מילים, שי ולי, ופירושו מתנה בשבילי. המילה שי היא מילה עתיקה למתנה. השם נשמע קרוב לשמות שילה ושילת, וניתן בעיקר לבנות.", ["שילת", "שיילי"])
n("עיליי", "עיליי הוא כתיב של השם עילי, שבא מהמילה עילי, עליון ונעלה. הכתיב עם שתי אותיות י מסמן את ההגייה בסוף השם. השם נשמע קרוב גם לעילאי, שמו של חכם בתלמוד.", ["עילי"])
n("פסיה", "פסיה הוא שם ביידיש, וכנראה הוא צורה של בתיה, שם מקראי שפירושו בת ה׳. ביידיש נבנו מבתיה הרבה צורות, למשל פעסיל ופעשא. השם היה נפוץ בקהילות של מזרח אירופה.", ["פסי"])
n("פראדל", "פראדל הוא שם ביידיש, וכנראה הוא צורת חיבה של פרידה, שם שבא מהמילה היידית פריידה, שמחה. ביידיש צורות חיבה רבות נבנו עם הסיומת ל. השם נשמר בקהילות חסידיות עד היום.", ["פראדי"])
n("שנהב", "שנהב הוא החומר הלבן והקשה שממנו בנויים החטים של הפיל. בעולם העתיק עשו ממנו כלים וקישוטים יקרים, והוא היה סחורה יקרה כבר בימי קדם. כשם, שנהב מביא תמונה של לובן ושל ערך, והוא ניתן בעיקר לבנות.", [])
n("מוריאל", "מוריאל הוא שם עברי חדש שבנוי מהמילים מורי ואל, ופירושו אלוהים הוא המורה שלי. השם נשמע קרוב לשמות מוריה ואוריאל. בצרפתית יש שם בצליל דומה, מוריאל, שמקורו קלטי.", ["מורי"])
n("רונאל", "רונאל הוא שם עברי חדש שבנוי מהמילים רון ואל, ופירושו שיר לאלוהים. המילה רון באה מהשורש ר־נ־ן, שממנו גם רינה ורננה. השם נשמע קרוב לרון ולרונאל, וניתן בעיקר לבנים.", ["רנאל"])
n("מלי", "מלי הוא שם קצר, צורת חיבה של שמות כמו מלכה, אמליה ושמואלה. בעברית השם נשמע גם כמו מילה של מלאות. השם היה נפוץ בארץ בשנות החמישים והשישים, ונשמע קצר ורך.", ["מאלי"])
n("מיי", "מיי הוא שם אנגלי, שפירושו החודש מאי, חודש האביב. באנגלית הוא היה גם צורת חיבה של מרים ושל מרגרט. השם קצר ופשוט, וניתן בעיקר לבנות במשפחות שחיות בין עברית לאנגלית.", [])
n("שלומי", "שלומי הוא שם עברי מהמילה שלום, והוא מופיע כבר בתורה, כשמו של אביו של אחיהוד נשיא שבט אשר. בארץ שלומי הוא גם שמה של עיר קטנה בגליל המערבי, ליד הגבול. השם היה נפוץ בשנות השישים והשבעים.", ["שלום"])
n("לאו", "לאו הוא שם בינלאומי שבא מהמילה הלטינית לאריה. השם מוכר בשפות רבות של אירופה, ובאיטלקית ובגרמנית הוא נפוץ מאוד. כמה אפיפיורים נשאו את השם הזה.", ["ליאו"])
n("אילעי", "אילעי הוא כתיב של השם אלעאי, שמו של חכם בתלמוד, רבי אלעאי. השם כנראה קשור למילה הארמית עלאי, עליון. הכתיב בלי האות א בסוף נשמע אותו דבר, והשם ניתן בעיקר לבנים.", ["אלעאי", "אילעאי"])
n("יניר", "יניר הוא שם עברי מהשורש נ־י־ר, שממנו באה המילה ניר, שדה שנחרש לראשונה. פירושו יחרוש שדה חדש, והוא מביא תמונה של התחלה ושל עבודת אדמה. השם היה נפוץ בארץ בשנות השישים והשבעים.", [])
n("אופרי", "אופרי הוא כתיב של עופרי, שם עברי חדש שבנוי מהמילה עופר, צבי צעיר. פירושו העופר שלי. הכתיב עם האות א נפוץ פחות, אבל נשמע אותו דבר. השם ניתן גם לבנים וגם לבנות.", [])
n("ניקה", "ניקה היא המילה היוונית לניצחון, וגם שמה של אלת הניצחון במיתולוגיה היוונית. מאותה מילה באים שמות המוכרים רבים, כמו ניקולאי, ניקול וניקיטה. ברוסית ניקה הוא גם צורת חיבה של ורוניקה.", ["ניקי"])
n("אורפז", "אורפז הוא שם עברי חדש שבנוי משתי מילים, אור ופז, ופירושו אור של זהב. המילה פז היא מילה עתיקה לזהב טהור, והיא מוכרת הרבה מהשירה העברית הקדומה. השם ניתן בעיקר לבנות.", [])
n("מיטב", "מיטב היא מילה עברית שפירושה הטוב ביותר, החלק המובחר של דבר. מאותו שורש, י־ט־ב, באות המילים טוב והיטיב. כשם, מיטב מביא את הרעיון של משהו יקר ונבחר.", [])
n("דוריה", "דוריה הוא שם עברי חדש שבנוי מהמילה דור ומהסיומת יה, ופירושו דור של אלוהים. השם נשמע קרוב לשמות דורית ודורון. באיטלקית יש שם משפחה ידוע בצליל זהה.", ["דורית"])
n("רויטל", "רויטל הוא שם עברי חדש שבנוי משתי מילים, רווי וטל, ופירושו רווה בטל. הטל הוא הלחות שיורדת בלילות ומשקה את הצמחים גם בקיץ. השם היה נפוץ מאוד בארץ בשנות השבעים.", [])
n("ליפז", "ליפז הוא שם עברי חדש שבנוי משתי מילים, לי ופז, ופירושו יש לי זהב. המילה פז היא מילה עתיקה לזהב טהור. מוכרת גם הצורה לי־פז, עם מקף בין שתי המילים.", ["לי-פז"])
n("אלן", "אלן הוא שם בינלאומי שמקורו כנראה בשפות הקלטיות, ופירושו לא ברור. בצרפתית ובאנגלית הוא נפוץ מאוד, ובעברית הוא נשמע גם קרוב למילים אלון ואילן. השם ניתן גם לבנים וגם לבנות.", [])
n("אושרת", "אושרת הוא שם עברי מהמילה אושר, שמחה ושלווה. מאותו שורש, א־ש־ר, באים גם השמות אשר, אושרי ואושרה. השם היה נפוץ בארץ בשנות השבעים והשמונים, וניתן לבנות.", ["אושרה", "אושרית"])
n("ולריה", "ולריה הוא שם לטיני שבא מהמילה ולרה, להיות חזק ובריא. ברומא העתיקה זה היה שמה של משפחה ידועה. השם נפוץ בשפות של אירופה, ובאיטלקית ובשפה הספרדית מוכרת גם הצורה ולריו לבנים.", [])
n("אל", "אל היא אחת המילים העתיקות לאלוהים, והיא מופיעה בתוך שמות עבריים רבים, כמו אליהו, מיכאל ואריאל. כשם בפני עצמו, אל קצר מאוד ונדיר. באנגלית יש שם בצליל זהה, שהוא צורה קצרה של אלן או של אלכסנדר.", [])
n("אוולין", "אוולין הוא שם אנגלי וצרפתי, שבמקור כנראה היה שם משפחה ממוצא נורמני. באנגלית הוא ניתן היום בעיקר לבנות, והוא נפוץ מאוד בשנים האחרונות. הכתיב העברי עם שתי אותיות ו מסמן את ההגייה של האות v.", [])
n("עטל", "עטל הוא שם חדש, וכנראה הוא צירוף של עטרה, כתר, ושל טל. כמו שמות עבריים חדשים רבים, הוא מצרף מילים קצרות לשם אחד. השם נשמע קרוב לעטיל ולעטרה.", ["עטיל"])
n("דניס", "דניס הוא שם שבא מהשם היווני דיוניסיוס, שמו של אל היין והחגיגה ביוון העתיקה. בצרפתית ובאנגלית השם נפוץ, ובצרפתית מוכרת גם הצורה דניז לבנות. בעברית השם נשמע קרוב לשם דני.", [])
n("הילאי", "הילאי הוא שם עברי חדש, וכנראה הוא בא מהמילה הילה, עיגול של אור סביב הירח או השמש. הסיומת אי מופיעה בשמות עבריים רבים, כמו עילאי ונתנאי. השם ניתן בעיקר לבנים.", [])
n("ורוניקה", "ורוניקה הוא שם בינלאומי, שלפי אחד ההסברים בא מהמילים הלטיניות ורה איקון, תמונה אמיתית. לפי הסבר אחר הוא צורה של השם היווני ברניקי, נושאת הניצחון. השם נפוץ בשפות רבות של אירופה.", ["ניקה"])
n("בל", "בל היא המילה הצרפתית ליפה, והיא גם צורה קצרה של שמות כמו איזבל ואנבל. בעברית השם קצר ופשוט. בשפות אחרות המילה בל פירושה פעמון, ולכן יש לשם גם צליל של צלצול.", [])
n("שיאל", "שיאל הוא שם עברי חדש שבנוי מהמילים שי ואל, ופירושו מתנה מאלוהים. המילה שי היא מילה עתיקה למתנה. השם ניתן גם לבנים וגם לבנות, והוא נשמע קרוב גם לשם שאול ולשמות שמסתיימים באל.", ["סיאל"])
n("יאנה", "יאנה היא צורה סלאבית של יוחנה, שם שבא מהעברית ופירושו ה׳ חנן. ברוסית, באוקראינית ובצ׳כית השם נפוץ מאוד. מוכרת גם הצורה הגברית יאן, והשם נשמע קצר ורך בכל שפה.", ["יאן"])
n("יוסי", "יוסי הוא צורת חיבה של יוסף, והוא היה נפוץ כבר בימי המשנה, כשמם של כמה חכמים, כמו רבי יוסי. בעברית של היום השם נעשה שם בפני עצמו. השם יוסף פירושו יוסיף, ה׳ יוסיף לי בן.", [])
n("אלדד", "אלדד הוא שם מקראי, ובספר במדבר אלדד הוא אחד משני הזקנים שהתנבאו במחנה, יחד עם מידד. השם בנוי מהמילים אל ודד, אהוב, ופירושו אהוב האל. השם היה נפוץ בארץ בשנות החמישים והשישים.", [])
n("לאל", "לאל הוא שם מקראי, ובספר במדבר הוא אביו של אליסף, נשיא בית אב בשבט לוי. השם בנוי מהמילה אל, ופירושו לאלוהים. בעברית החדשה השם נדיר, ונשמע קרוב לליאל.", ["ליאל"])
n("לוריא", "לוריא הוא שם משפחה ידוע, שמו של רבי יצחק לוריא, המקובל שחי בצפת וכינויו האר״י. כשם פרטי לוריא נדיר, והוא ניתן בעיקר לבנים. השם נשמע קרוב גם ללורי וללירי.", [])
n("עיינה", "עיינה הוא שם עברי חדש, וכנראה הוא בא מהמילה עין או מהמילה מעיין. המעיין הוא מקור מים טבעיים, והוא נזכר הרבה בשמות של מקומות בארץ. השם נשמע קרוב לעינת ולעינב.", ["עינת"])
n("אילעאי", "אילעאי הוא כתיב של השם אלעאי, שמו של חכם בתלמוד, רבי אלעאי, אביו של רבי יהודה. השם כנראה קשור למילה הארמית עלאי, עליון. הכתיב עם האות י מסמן את ההגייה של התנועה הראשונה.", ["אלעאי", "אילעי"])
n("פולינה", "פולינה היא צורה רוסית ומזרח־אירופית של השם פאולינה, צורת הנקבה של פאולוס, שם לטיני שפירושו קטן. השם נפוץ ברוסיה ובאוקראינה. ברוסית מוכרת גם צורת החיבה פוליה.", [])
n("איריס", "איריס הוא שמו של פרח, וביוונית העתיקה זה גם שמה של אלת הקשת שבענן. בארץ גדלים מינים רבים של איריס בר, ובעברית הם נקראים גם אירוסים, ורבים מהם נדירים ומוגנים. השם היה נפוץ בארץ בשנות השישים.", [])
n("ארטיום", "ארטיום הוא שם רוסי שבא מהשם היווני ארטמיוס, שקשור לארטמיס, אלת הציד היוונית. השם נפוץ ברוסיה ובאוקראינה. מוכרת גם הצורה ארטם, והשם הגיע לארץ עם העלייה מברית המועצות.", [])
